# Review package: ac88672ae36aebd2a0996ed6716d36134e127ce0..HEAD

## Commits
5a7d8b2 Add greet function with tests

## Files changed
 greet.js      | 16 ++++++++++++++++
 greet.test.js | 33 +++++++++++++++++++++++++++++++++
 2 files changed, 49 insertions(+)

## Diff
diff --git a/greet.js b/greet.js
new file mode 100644
index 0000000..64c78bc
--- /dev/null
+++ b/greet.js
@@ -0,0 +1,16 @@
+/**
+ * Returns a formatted greeting string.
+ *
+ * @param {string} name - The name to greet
+ * @returns {string} A formatted greeting
+ */
+function greet(name) {
+  // Handle empty, null, undefined, or whitespace-only input
+  if (!name || typeof name !== 'string' || name.trim() === '') {
+    return 'Hello, there!';
+  }
+
+  return `Hello, ${name.trim()}!`;
+}
+
+module.exports = { greet };
diff --git a/greet.test.js b/greet.test.js
new file mode 100644
index 0000000..feaac61
--- /dev/null
+++ b/greet.test.js
@@ -0,0 +1,33 @@
+const test = require('node:test');
+const assert = require('node:assert');
+const { greet } = require('./greet');
+
+test('greet returns formatted greeting for valid name', () => {
+  const result = greet('Alice');
+  assert.strictEqual(typeof result, 'string');
+  assert.ok(result.includes('Alice'));
+});
+
+test('greet handles empty string gracefully', () => {
+  const result = greet('');
+  assert.strictEqual(typeof result, 'string');
+  assert.ok(result.length > 0);
+});
+
+test('greet handles undefined gracefully', () => {
+  const result = greet(undefined);
+  assert.strictEqual(typeof result, 'string');
+  assert.ok(result.length > 0);
+});
+
+test('greet handles null gracefully', () => {
+  const result = greet(null);
+  assert.strictEqual(typeof result, 'string');
+  assert.ok(result.length > 0);
+});
+
+test('greet handles whitespace-only input', () => {
+  const result = greet('   ');
+  assert.strictEqual(typeof result, 'string');
+  assert.ok(result.length > 0);
+});

